const hex=rgb=>Buffer.from(rgb).toString('hex');
function map(rgb){const k=hex(rgb);if(!mapping.has(k)){let best=entries[0],dist=Infinity;const v=lab(rgb);for(const e of entries){const d=e.lab.reduce((s,n,i)=>s+(n-v[i])**2,0);if(d<dist){dist=d;best=e;}}mapping.set(k,best.rgb);}return mapping.get(k);}
