function convert(u){if(cache.has(u))return cache.get(u);const im=png.decode(Buffer.from(u.split(',')[1],'base64')),d=Buffer.from(im.data);for(let i=0;i<d.length;i+=4){if(d[i+3]){const rgb=map(Array.from(d.subarray(i,i+3)));if(rgb.some((v,j)=>v!==d[i+j]))changedPixels++;d.set(rgb,i);assert(allowed.has(hex(d.subarray(i,i+3))));checkedPixels++;}assert.equal(d[i+3],im.data[i+3]);}const result='data:image/png;base64,'+png.encode(im.width,im.height,d).toString('base64');cache.set(u,result);return result;}
for(const l of p.layers)for(const f of Object.values(l.frameData||{}))if(f.dataURL)f.dataURL=convert(f.dataURL);
