const cmp=structuredClone(p);cmp.layers.forEach((l,i)=>Object.keys(l.frameData||{}).forEach(k=>l.frameData[k].dataURL=before.layers[i].frameData[k].dataURL));cmp.spriteSheets.forEach((s,i)=>s.imageDataURL=before.spriteSheets[i].imageDataURL);cmp.palette=before.palette;cmp.bgColor=before.bgColor;assert.deepEqual(cmp,before);
