function scene(p){const c=createCanvas(160,128),cx=c.getContext('2d');for(const o of p.sceneAssembly.objects){const si=p.spriteSheets.findIndex(s=>s.name===o.material);assert(si>=0,o.material);const ai=Math.max(0,p.spriteSheets[si].actions.findIndex(a=>a.name===o.variant)),im=frameCanvas(p,si,ai);cx.save();cx.translate(o.x,o.y);if(o.flip){cx.translate(im.width,0);cx.scale(-1,1);}cx.drawImage(im,0,0);cx.restore();}return c;}
const preview=createCanvas(1280,512),cx=preview.getContext('2d');cx.imageSmoothingEnabled=false;cx.fillStyle='#d4d0cd';cx.fillRect(0,0,1280,512);cx.drawImage(scene(before),0,0,640,512);cx.drawImage(scene(p),640,0,640,512);fs.writeFileSync(path.join(dir,'before-after.png'),preview.toBuffer('image/png'));
